mapper.sql:
where r.reversal_of_id is null
  and r.work_day between #{q.from} and #{q.to}
  and w.plant_cd = #{q.plantCd}
  and r.shift_cd = #{q.shiftCd}
  and w.wo_no like '%' || #{q.keyword} || '%' escape '\'
  and w.item_id = #{q.itemId}
  and wp.proc_cd = #{q.procCd}
  and r.performed_by = #{q.workerId}
